<script setup>
import { onMounted, ref } from 'vue';
import QRCode from 'qrcode';
const emit=defineEmits(['close']);const busy=ref(false);const message=ref('');const qrSvg=ref('');
onMounted(async()=>{try{qrSvg.value=await QRCode.toString(window.location.href,{type:'svg',margin:1,width:180,color:{dark:'#102321',light:'#f3faf8'}})}catch{qrSvg.value=''}});
const download=async()=>{busy.value=true;message.value='Checking for a built Android package…';try{const response=await fetch('/releases/denta-spectra-v1.22.0-universal.apk');if(response.ok){const blob=await response.blob();const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='Denta-Spectra-v1.22.0.apk';a.click();URL.revokeObjectURL(url);message.value='Release artifact downloaded.'}else{message.value='No APK artifact is published yet. Use the GitHub Actions workflow to build a debug APK; no fake APK is generated.'}}catch{message.value='APK unavailable. Use GitHub Actions to build an Android package.'}finally{busy.value=false}};
</script>
<template><div class="modal-backdrop" @click.self="emit('close')"><section class="modal glass"><div class="modal-head"><div><div class="eyebrow">Android package · v1.22.0</div><h2>Get Denta Spectra</h2><p class="small">Web app and Capacitor project share the same Vue interface; native hardware access varies by device.</p></div><button class="close" @click="emit('close')">×</button></div><div class="two-col"><div class="inner"><div class="qr" aria-label="QR code linking to this web app"><div v-if="qrSvg" v-html="qrSvg"></div><span v-else class="small">QR unavailable</span></div><p class="footnote">Scan to open this web app on another device. This QR does not point to an APK binary.</p></div><div class="inner"><div class="control-row"><span class="small">Application ID</span><b>com.dentaspectra.odontology</b></div><div class="control-row"><span class="small">Web framework</span><b>Vue · JavaScript</b></div><div class="control-row"><span class="small">Native shell</span><b>Capacitor config included</b></div><div class="control-row"><span class="small">Build signature</span><b>CI-generated</b></div><button class="action primary" style="width:100%;margin-top:14px" :disabled="busy" @click="download">{{busy?'Checking…':'Download APK'}}</button><p class="footnote">{{message}}</p></div></div><div class="notice" style="margin-top:14px">A valid signed APK cannot be synthesized safely in a browser. The configured workflow builds a debug APK artifact; production distribution needs a signed release build and secure signing setup.</div></section></div></template>
<style scoped>.qr{display:grid;place-items:center;padding:8px}.qr :deep(svg){width:100%;max-width:180px;border-radius:12px}</style>
